const items = $input.all();
const response = items[0].json;
const vulnerabilities = response.vulnerabilities || [];
const totalResults = response.totalResults || 0;
const resultsPerPage = response.resultsPerPage || 2000;
const startIndex = response.startIndex || 0;
const executionStart = Date.now();

if (vulnerabilities.length === 0) {
  return [{
    json: {
      _isEmpty: true,
      totalResults: 0,
      parsedCount: 0,
      needsPagination: false,
      executionStart
    }
  }];
}

return vulnerabilities.map(item => {
  const cve = item.cve;

  // Description — prefer English
  const descriptions = cve.descriptions || [];
  const enDesc = descriptions.find(d => d.lang === 'en');
  const rawDesc = enDesc ? enDesc.value : (descriptions[0] ? descriptions[0].value : '');
  const description = rawDesc.replace(/'/g, "''").replace(/\$/g, "'||chr(36)||'");

  // CVSS: prefer v3.1 → v3.0 → v2 fallback
  const metrics = cve.metrics || {};
  const cvssV3data = ((metrics.cvssMetricV31 || []).length
    ? metrics.cvssMetricV31
    : (metrics.cvssMetricV30 || []))[0];
  const cvssV2data = (metrics.cvssMetricV2 || [])[0];
  const cvssV3 = cvssV3data ? cvssV3data.cvssData : null;
  const cvssV2 = cvssV2data ? cvssV2data.cvssData : null;

  // CWE — skip NVD internal placeholders
  let cweId = null;
  const weakness = (cve.weaknesses || [])[0];
  if (weakness && weakness.description && weakness.description[0]) {
    const val = weakness.description[0].value;
    if (val && !val.startsWith('NVD-CWE')) {
      cweId = val;
    }
  }

  // Configurations → JSONB string (null when absent)
  const configurationsRaw = (cve.configurations || []).length
    ? JSON.stringify(cve.configurations)
    : null;
  const configurations = configurationsRaw
    ? configurationsRaw.replace(/\$/g, "'||chr(36)||'")
    : null;

  // References → JSONB string stored as patch_references
  const refs = (cve.references || []).map(r => ({
    url: r.url,
    source: r.source || null,
    tags: r.tags || []
  }));
  const refsRaw = refs.length ? JSON.stringify(refs) : null;
  const patch_references = refsRaw
    ? refsRaw.replace(/\$/g, "'||chr(36)||'")
    : null;

  return {
    json: {
      cve_id:             cve.id,
      description,
      cvss_v3_base_score: cvssV3 ? cvssV3.baseScore    : null,
      cvss_v3_vector:     cvssV3 ? cvssV3.vectorString  : null,
      cvss_v3_severity:   cvssV3 ? cvssV3.baseSeverity  : null,
      cvss_v2_base_score: cvssV2 ? cvssV2.baseScore    : null,
      cwe_id:             cweId,
      published_date:     cve.published,
      last_modified_date: cve.lastModified || null,
      configurations,
      patch_references,
      _meta: {
        totalResults,
        parsedCount:     vulnerabilities.length,
        needsPagination: totalResults > startIndex + resultsPerPage,
        executionStart
      }
    }
  };
});

const upserted = $input.all();
const parseFirst = $('Parse NVD Response').first();
const meta = (parseFirst && parseFirst.json._meta) ? parseFirst.json._meta : {};
const executionTimeMs = Date.now() - (meta.executionStart || Date.now());
const needsPagination = meta.needsPagination || false;

return [{
  json: {
    recordsProcessed: upserted.length,
    totalResults:     meta.totalResults || upserted.length,
    needsPagination,
    executionTimeMs,
    auditStatus: needsPagination ? 'PARTIAL' : 'SUCCESS',
    errorMessage: needsPagination
      ? 'Only ' + upserted.length + ' of ' + meta.totalResults + ' CVEs fetched (NVD window > 2000). Implement loop pagination.'
      : null
  }
}];
